89	func cmdImport(args []string, w io.Writer) error {
90		var opts cmdOptions
91		var sourceDir string
92		var assetIDs stringListFlag
93		fs := newFlagSet("import", &opts)
94		fs.StringVar(&sourceDir, "source-dir", "", "源数据目录（必填，只读，不会被修改）")
95		fs.Var(&assetIDs, "asset-id", "要导入的资产编号（必填，可重复；重复编号按一项处理）")
96		if err := parseFlags(fs, args); err != nil {
97			return err
98		}
99		if err := requireFlag(fs, sourceDir, "source-dir"); err != nil {
100			return err
101		}
102		if len(assetIDs) == 0 {
103			return &usageError{msg: "命令 import 缺少必填参数 --asset-id（至少一项资产编号）"}
104		}
