111		outcome, err := importAssets(opts.dataDir, sourceDir, []string(assetIDs))
112		if err != nil {
113			return err
114		}
115		fmt.Fprintf(w, "已导入 %d 项资产（%s）。\n", len(outcome.assetIDs), strings.Join(outcome.assetIDs, ", "))
116		if outcome.plans > 0 {
