148	// importAssets 把 sourceDir 中编号为 assetIDs 的资产导入 targetDir。
149	// 源目录只读；目标目录无台账时在成功导入时创建。任何一步失败都整批失败，
150	// 两边原文件字节保持不变。
151	func importAssets(targetDir, sourceDir string, assetIDs []string) (*importOutcome, error) {
152		srcAbs, err := filepath.Abs(sourceDir)
153		if err != nil {
154			return nil, fmt.Errorf("无法解析源数据目录: %w", err)
155		}
156		dstAbs, err := filepath.Abs(targetDir)
157		if err != nil {
158			return nil, fmt.Errorf("无法解析目标数据目录: %w", err)
159		}
160		if srcAbs == dstAbs {
161			return nil, errors.New("源数据目录与目标数据目录相同：同一台账不能导入自身")
162		}
163		// 路径不同也可能指向同一台账文件（符号链接等），按文件再判一次。
164		srcPath := filepath.Join(srcAbs, dataFileName)
165		dstPath := filepath.Join(dstAbs, dataFileName)
166		if fi1, err1 := os.Stat(srcPath); err1 == nil {
167			if fi2, err2 := os.Stat(dstPath); err2 == nil && os.SameFile(fi1, fi2) {
168				return nil, errors.New("源与目标指向同一台账文件：同一台账不能导入自身")
169			}
170		}
171	
172		// 源台账必须已存在并通过整库一致性检查；源始终只读，绝不写入。
173		src, err := openSourceStore(srcAbs)
174		if err != nil {
175			return nil, err
176		}
177		// 目标：无台账时视为空库（成功导入时创建）；已有台账同样先做整库一致性检查。
178		dst, err := openStore(dstAbs)
179		if err != nil {
180			return nil, err
181		}
182		outcome, err := dst.mergeImport(src, assetIDs)
183		if err != nil {
184			return nil, err
185		}
186		// save 先校验合并后的整库一致性，再一次性原子写入；失败时目标原文件不变。
187		if err := dst.save(); err != nil {
188			return nil, err
189		}
190		return outcome, nil
191	}
192	
193	// mergeImport 在内存中把源台账的所选资产合并进目标数据：先做全部冲突与容量
194	// 检查，再一次性应用，任何失败都不会留下部分变更。调用方负责随后的原子保存。
195	func (s *store) mergeImport(src *store, assetIDs []string) (*importOutcome, error) {
196		// 重复编号按一项处理，保持首次出现的顺序。
197		selected := map[string]bool{}
198		ids := make([]string, 0, len(assetIDs))
199		for _, id := range assetIDs {
200			if !selected[id] {
201				selected[id] = true
202				ids = append(ids, id)
203			}
204		}
205		// 所选资产必须存在于源，且编号在目标中不存在。
206		assets := make([]*Asset, 0, len(ids))
207		for _, id := range ids {
208			a := src.findAsset(id)
209			if a == nil {
210				return nil, fmt.Errorf("%w: 源台账中不存在资产编号 %q", errNotFound, id)
211			}
212			if s.findAsset(id) != nil {
213				return nil, fmt.Errorf("%w: 资产编号 %q 在目标台账中已存在，整批拒绝导入", errConflict, id)
214			}
215			assets = append(assets, a)
216		}
217		// 所选资产的全部工单，按源工单序号升序重新分配编号。
218		tickets := make([]*Ticket, 0)
219		for _, t := range src.data.Tickets {
220			if selected[t.AssetID] {
221				tickets = append(tickets, t)
222			}
223		}
224		sort.SliceStable(tickets, func(i, j int) bool {
225			ni, _ := parseTicketSeq(tickets[i].ID)
226			nj, _ := parseTicketSeq(tickets[j].ID)
227			return ni < nj
228		})
229		// 工单编号容量：与 report 同一约束，可分配的最大序号为 math.MaxInt-1。
230		if len(tickets) > math.MaxInt-s.data.NextTicketSeq {
231			return nil, fmt.Errorf(
232				"%w: 目标工单编号容量不足：下一序号 %d 无法容纳 %d 张导入工单，整批拒绝导入",
233				errConflict, s.data.NextTicketSeq, len(tickets))
234		}
235		// 所选工单的任一请求标识已在目标绑定时整批拒绝，不改请求标识。
236		srcReqByTicket := map[string]*requestBinding{}
237		for i := range src.data.Requests {
238			r := &src.data.Requests[i]
239			srcReqByTicket[r.TicketID] = r
240		}
241		for _, t := range tickets {
242			r := srcReqByTicket[t.ID]
243			if r == nil {
244				return nil, fmt.Errorf("数据内部错误：源工单 %s 缺少报修请求绑定", t.ID)
245			}
246			if s.findRequest(r.RequestID) != nil {
247				return nil, fmt.Errorf(
248					"%w: 所选工单的请求标识 %q 已在目标台账绑定，整批拒绝导入", errConflict, r.RequestID)
249			}
250		}
251		// 所选资产的全部履历，按源履历序号升序，在目标最大序号之后依次分配。
252		events := make([]Event, 0)
253		for _, e := range src.data.Events {
254			if selected[e.AssetID] {
255				events = append(events, e)
256			}
257		}
258		sort.SliceStable(events, func(i, j int) bool { return events[i].Seq < events[j].Seq })
259		maxSeq := 0
260		for _, e := range s.data.Events {
261			if e.Seq > maxSeq {
262				maxSeq = e.Seq
263			}
264		}
265		// 履历序号容量：与 nextEventSeq 同一约束，可分配的最大序号为 math.MaxInt。
266		if len(events) > math.MaxInt-maxSeq {
267			return nil, fmt.Errorf(
268				"%w: 目标履历序号容量不足：当前最大序号 %d 无法容纳 %d 条导入履历，整批拒绝导入",
269				errConflict, maxSeq, len(events))
270		}
271		// 所选工单的全部备件领用记录，按源领用履历的全库序号整体排序（领用编号
272		// 只定位记录，编号大小不代表领用先后），再按此顺序重新分配领用编号。
273		srcTicketIDs := map[string]bool{}
274		for _, t := range tickets {
275			srcTicketIDs[t.ID] = true
276		}
277		srcWithdrawSeq := map[string]int{}
278		for _, e := range src.data.Events {
279			if e.Kind == eventPartWithdraw {
280				srcWithdrawSeq[e.WithdrawalID] = e.Seq
281			}
282		}
283		parts := make([]*PartWithdrawal, 0)
284		for _, p := range src.data.Parts {
285			if srcTicketIDs[p.TicketID] {
286				parts = append(parts, p)
287			}
288		}
289		sort.SliceStable(parts, func(i, j int) bool {
290			return srcWithdrawSeq[parts[i].ID] < srcWithdrawSeq[parts[j].ID]
291		})
292		// 领用编号容量：与 withdrawPart 同一约束，可分配的最大序号为 math.MaxInt-1。
293		if len(parts) > math.MaxInt-s.data.NextPartSeq {
294			return nil, fmt.Errorf(
295				"%w: 目标领用编号容量不足：下一序号 %d 无法容纳 %d 笔导入领用，整批拒绝导入",
296				errConflict, s.data.NextPartSeq, len(parts))
297		}
298		// 所选工单的全部附件索引（有效与已撤销都复制），按源登记履历的全库序号
299		// 整体排序（附件编号只定位记录，编号大小不代表登记先后），再按此顺序重新
300		// 分配附件编号。只复制索引记录与履历，不复制资料文件；文件当前不可用不使
301		// 导入失败。
302		srcAttachRegSeq := map[string]int{}
303		for _, e := range src.data.Events {
304			if e.Kind == eventAttach {
305				srcAttachRegSeq[e.AttachmentID] = e.Seq
306			}
307		}
308		attachments := make([]*Attachment, 0)
309		for _, a := range src.data.Attachments {
310			if srcTicketIDs[a.TicketID] {
311				attachments = append(attachments, a)
312			}
313		}
314		sort.SliceStable(attachments, func(i, j int) bool {
315			return srcAttachRegSeq[attachments[i].ID] < srcAttachRegSeq[attachments[j].ID]
316		})
317		// 附件编号容量：与 attach 同一约束，可分配的最大序号为 math.MaxInt-1。
318		if len(attachments) > math.MaxInt-s.data.NextAttachSeq {
319			return nil, fmt.Errorf(
320				"%w: 目标附件编号容量不足：下一序号 %d 无法容纳 %d 条导入附件索引，整批拒绝导入",
321				errConflict, s.data.NextAttachSeq, len(attachments))
322		}
323	
324		// 检查全部通过，一次性应用合并。资产编号、名称、位置、状态与工单的描述、
325		// 终态内容、负责人等业务信息原样保留；履历时间保留原瞬间与小数秒精度。
326		for _, a := range assets {
327			na := *a
328			s.data.Assets = append(s.data.Assets, &na)
329		}
330		// 所选资产的保养计划原样复制（内容、首次到期日、间隔与下一到期日不变）；
331		// 保养履历已随上方资产履历筛选一并复制，完成链自然接续。目标已有计划不变。
332		planCount := 0
333		for _, p := range src.data.Plans {
334			if selected[p.AssetID] {
335				np := *p
336				s.data.Plans = append(s.data.Plans, &np)
337				planCount++
338			}
339		}
340		outcome := &importOutcome{assetIDs: ids, plans: planCount}
341		remap := map[string]string{}
342		next := s.data.NextTicketSeq
343		for _, t := range tickets {
344			nt := *t
345			nt.ID = fmt.Sprintf("T%04d", next)
346			remap[t.ID] = nt.ID
347			s.data.Tickets = append(s.data.Tickets, &nt)
348			r := srcReqByTicket[t.ID]
349			s.data.Requests = append(s.data.Requests, requestBinding{
350				RequestID:   r.RequestID,
351				AssetID:     r.AssetID,
352				Description: r.Description,
353				TicketID:    nt.ID,
354			})
355			outcome.tickets = append(outcome.tickets, ticketRemap{OldID: t.ID, NewID: nt.ID})
356			next++
357		}
358		s.data.NextTicketSeq = next
359		// 备件领用记录按源领用顺序重新分配领用编号，工单引用同步替换；
360		// 数量、累计退回与说明等业务信息原样保留。
361		partIDs := map[string]string{}
362		nextPart := s.data.NextPartSeq
363		for _, p := range parts {
364			np := *p
365			np.ID = fmt.Sprintf("P%04d", nextPart)
366			np.TicketID = remap[p.TicketID]
367			partIDs[p.ID] = np.ID
368			s.data.Parts = append(s.data.Parts, &np)
369			outcome.parts = append(outcome.parts, partRemap{OldID: p.ID, NewID: np.ID})
370			nextPart++
371		}
372		s.data.NextPartSeq = nextPart
373		// 附件索引按源登记顺序重新分配附件编号，工单引用同步替换；
374		// 路径、撤销状态、说明与撤销理由等业务信息原样保留。
375		attachIDs := map[string]string{}
376		nextAttach := s.data.NextAttachSeq
377		for _, a := range attachments {
378			na := *a
379			na.ID = fmt.Sprintf("A%04d", nextAttach)
380			na.TicketID = remap[a.TicketID]
381			attachIDs[a.ID] = na.ID
382			s.data.Attachments = append(s.data.Attachments, &na)
383			outcome.attachments = append(outcome.attachments, attachRemap{OldID: a.ID, NewID: na.ID})
384			nextAttach++
385		}
386		s.data.NextAttachSeq = nextAttach
387		seq := maxSeq
388		seqRemap := map[int]int{}
389		for _, e := range events {
390			seq++
391			ne := e
392			ne.Seq = seq
393			ne.TicketID = remap[e.TicketID]
394			ne.WithdrawalID = partIDs[e.WithdrawalID]
395			ne.AttachmentID = attachIDs[e.AttachmentID]
396			if e.Kind == eventPlanRevoke {
397				// 撤销履历的目标完成序号随履历重编号同步替换：目标在源序号顺序中
398				// 先于撤销出现（源台账已通过一致性检查），此处必然已有映射。
399				ne.TargetSeq = seqRemap[e.TargetSeq]
400			}
401			seqRemap[e.Seq] = seq
402			if e.Kind == eventPlanDone {
403				outcome.completions = append(outcome.completions, completionRemap{OldSeq: e.Seq, NewSeq: seq})
404			}
405			s.data.Events = append(s.data.Events, ne)
406		}
407		return outcome, nil
408	}
409

