	// 已关闭旧单查询仍显示原报修地点。
	if out := runOK("ticket", "--data-dir", dir, "--ticket-id", "T0001"); !strings.Contains(out, "报修地点: 一楼") {
		t.Fatalf("已关闭旧单应保持报修地点 一楼: %s", out)
	}
}

